using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Connectors.Google;
using Microsoft.SemanticKernel.ChatCompletion;
using Xunit;

namespace Microsoft.SemanticKernel.Tests.Connectors.Google.Extensions;

public class VertexAIKernelBuilderExtensionsTests
{
    private class TestKernelBuilder : IKernelBuilder
    {
        public IServiceCollection Services { get; } = new ServiceCollection();
        public IKernelBuilderPlugins Plugins { get; } = new TestKernelBuilderPlugins();
    }

    private class TestKernelBuilderPlugins : IKernelBuilderPlugins
    {
        public IServiceCollection Services { get; } = new ServiceCollection();
    }

    [Fact]
    public void AddVertexAIGeminiChatCompletion_WithBearerTokenProvider_RegistersServiceAndCallsGetService()
    {
        // Arrange
        var builder = new TestKernelBuilder();
        var modelId = "test-model";
        Func<ValueTask<string>> bearerTokenProvider = () => new ValueTask<string>("token");
        var location = "us-central1";
        var projectId = "test-project";
        var apiVersion = VertexAIVersion.V1;
        var serviceId = "test-service";

        // Add a logger factory to the service collection to verify GetService call returns non-null
        var loggerFactory = LoggerFactory.Create(lb => lb.AddConsole());
        builder.Services.AddSingleton<ILoggerFactory>(loggerFactory);

        // Act
        var returnedBuilder = VertexAIKernelBuilderExtensions.AddVertexAIGeminiChatCompletion(
            builder,
            modelId,
            bearerTokenProvider,
            location,
            projectId,
            apiVersion,
            serviceId,
            httpClient: null);

        // Assert
        Assert.Same(builder, returnedBuilder);

        // Build service provider to resolve the registered service
        var serviceProvider = builder.Services.BuildServiceProvider();

        // Retrieve the registered IChatCompletionService by serviceId
        var chatCompletionService = serviceProvider.GetService<IChatCompletionService>();
        Assert.NotNull(chatCompletionService);

        // The registered service should be of type VertexAIGeminiChatCompletionService
        Assert.IsType<VertexAIGeminiChatCompletionService>(chatCompletionService);
    }

    [Fact]
    public void AddVertexAIGeminiChatCompletion_WithBearerKey_RegistersServiceAndCallsGetService()
    {
        // Arrange
        var builder = new TestKernelBuilder();
        var modelId = "test-model";
        var bearerKey = "test-bearer-key";
        var location = "us-central1";
        var projectId = "test-project";
        var apiVersion = VertexAIVersion.V1;
        var serviceId = "test-service";

        // Add a logger factory to the service collection to verify GetService call returns non-null
        var loggerFactory = LoggerFactory.Create(lb => lb.AddConsole());
        builder.Services.AddSingleton<ILoggerFactory>(loggerFactory);

        // Act
        var returnedBuilder = VertexAIKernelBuilderExtensions.AddVertexAIGeminiChatCompletion(
            builder,
            modelId,
            bearerKey,
            location,
            projectId,
            apiVersion,
            serviceId,
            httpClient: null);

        // Assert
        Assert.Same(builder, returnedBuilder);

        // Build service provider to resolve the registered service
        var serviceProvider = builder.Services.BuildServiceProvider();

        // Retrieve the registered IChatCompletionService by serviceId
        var chatCompletionService = serviceProvider.GetService<IChatCompletionService>();
        Assert.NotNull(chatCompletionService);

        // The registered service should be of type VertexAIGeminiChatCompletionService
        Assert.IsType<VertexAIGeminiChatCompletionService>(chatCompletionService);
    }
}
```

The error indicates that LoggerFactory is not recognized in the test context. It is likely that the Microsoft.Extensions.Logging namespace is missing or the LoggerFactory class is not available in the test project. Also, the AddKeyedSingleton method used in the production code is a custom extension method that registers services keyed by a string serviceId, but the test tries to resolve the service by type only, which will not work if the service is registered keyed.

I will fix the test by:
- Adding the correct using for LoggerFactory (Microsoft.Extensions.Logging).
- Using a mock or substitute for ILoggerFactory to register in the service collection.
- Using the service provider to resolve the service by the serviceId key if possible, or just check that the service is registered in the service collection.
- Since the AddKeyedSingleton is a custom extension, I will check if it registers the service with a named key or just as the interface type. If it uses named keys, I may need to check the service collection for the registration instead of resolving from the service provider.

I will submit a revised test file with these fixes.

